using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle.FourNegative.SecondPeakEqualOuter;
internal sealed class StrictDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Exact strict physical inventories", H("Physical construction"),
        Blocks(Paragraph(Text("For every 2<=a<c<b,d=a, take W masks full xor (s-1), (s-1) xor (t-1), and t-1, and complementary V masks v-1 and full xor (v-1). The selector proof establishes the literal bit-submask t-1 subset s-1, including the binary 101 boundary, rather than only t<=s. Banks in W,X,U,V order are the first W mask; all X; all U plus the selected V mask plus the middle W mask; remaining V plus the last W mask. Insert actual fresh k at the end of the X-positive bank immediately before nX. The cut is the actual prefix length; no popcount API or cyclic transport is needed."))), []));
}
